package com.craftmarket.service.impl;

import com.baomidou.mybatisplus.core.conditions.query.QueryWrapper;
import com.baomidou.mybatisplus.extension.service.impl.ServiceImpl;
import com.craftmarket.entity.MarketActivity;
import com.craftmarket.mapper.MarketActivityMapper;
import com.craftmarket.service.MarketActivityService;
import com.craftmarket.vo.ActivityVO;
import org.springframework.beans.BeanUtils;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.time.LocalDateTime;
import java.util.List;
import java.util.stream.Collectors;

/**
 * 市集活动服务实现类
 */
@Service
public class MarketActivityServiceImpl extends ServiceImpl<MarketActivityMapper, MarketActivity> implements MarketActivityService {

    @Override
    @Transactional
    public ActivityVO createActivity(MarketActivity activity) {
        // 设置默认值
        activity.setStatus("DRAFT"); // 默认为草稿状态
        activity.setCreateTime(LocalDateTime.now());

        save(activity);

        ActivityVO activityVO = new ActivityVO();
        BeanUtils.copyProperties(activity, activityVO);
        return activityVO;
    }

    @Override
    @Transactional
    public ActivityVO updateActivity(MarketActivity activity) {
        MarketActivity existing = getById(activity.getId());
        if (existing == null) {
            throw new IllegalArgumentException("活动不存在");
        }

        activity.setUpdateTime(LocalDateTime.now());
        updateById(activity);

        ActivityVO activityVO = new ActivityVO();
        BeanUtils.copyProperties(activity, activityVO);
        return activityVO;
    }

    @Override
    public ActivityVO getActivityDetail(Long id) {
        MarketActivity activity = getById(id);
        if (activity == null) {
            throw new IllegalArgumentException("活动不存在");
        }

        ActivityVO activityVO = new ActivityVO();
        BeanUtils.copyProperties(activity, activityVO);
        return activityVO;
    }

    @Override
    public List<ActivityVO> getActivityList(String status) {
        QueryWrapper<MarketActivity> queryWrapper = new QueryWrapper<>();
        if (status != null && !status.trim().isEmpty()) {
            queryWrapper.eq("status", status);
        }
        queryWrapper.orderByDesc("create_time");

        List<MarketActivity> activities = list(queryWrapper);

        return activities.stream()
                .map(activity -> {
                    ActivityVO activityVO = new ActivityVO();
                    BeanUtils.copyProperties(activity, activityVO);
                    return activityVO;
                })
                .collect(Collectors.toList());
    }

    @Override
    @Transactional
    public ActivityVO updateActivityStatus(Long id, String status) {
        MarketActivity activity = getById(id);
        if (activity == null) {
            throw new IllegalArgumentException("活动不存在");
        }

        activity.setStatus(status);
        activity.setUpdateTime(LocalDateTime.now());

        updateById(activity);

        ActivityVO activityVO = new ActivityVO();
        BeanUtils.copyProperties(activity, activityVO);
        return activityVO;
    }

    @Override
    @Transactional
    public void deleteActivity(Long id) {
        MarketActivity activity = getById(id);
        if (activity == null) {
            throw new IllegalArgumentException("活动不存在");
        }

        // 检查是否有关联的摊位
        // 这里应该检查是否有摊位订单，为了简化，直接删除

        return removeById(id);
    }
}

package com.craftmarket.service;

import com.baomidou.mybatisplus.extension.service.IService;
import com.craftmarket.entity.MarketActivity;
import com.craftmarket.vo.ActivityVO;

import java.util.List;

/**
 * 市集活动服务接口
 */
public interface MarketActivityService extends IService<MarketActivity> {

    /**
     * 创建活动
     *
     * @param activity 活动信息
     * @return 创建的活动信息
     */
    ActivityVO createActivity(MarketActivity activity);

    /**
     * 更新活动信息
     *
     * @param activity 活动信息
     * @return 更新后的活动信息
     */
    ActivityVO updateActivity(MarketActivity activity);

    /**
     * 获取活动详情
     *
     * @param id 活动ID
     * @return 活动信息
     */
    ActivityVO getActivityDetail(Long id);

    /**
     * 获取活动列表
     *
     * @param status 状态（可选）
     * @return 活动列表
     */
    List<ActivityVO> getActivityList(String status);

    /**
     * 更新活动状态
     *
     * @param id     活动ID
     * @param status 状态
     * @return 更新后的活动信息
     */
    ActivityVO updateActivityStatus(Long id, String status);

    /**
     * 删除活动
     *
     * @param id 活动ID
     */
    void deleteActivity(Long id);

    /**
     * 获取即将开始的活动
     *
     * @param limit 限制数量
     * @return 即将开始的活动列表
     */
    List<ActivityVO> getUpcomingActivities(int limit);
}
